#include <iostream>
#include <vector>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;
    Fenwick(int n) : n(n), bit(n + 1, 0) {}
    void add(int i, long long value) {
        for (; i <= n; i += i & -i) bit[i] += value;
    }
    long long sumPrefix(int i) {
        long long result = 0;
        for (; i > 0; i -= i & -i) result += bit[i];
        return result;
    }
    long long rangeSum(int l, int r) {
        return sumPrefix(r) - sumPrefix(l - 1);
    }
};

int main() {
    Fenwick fenwick(8);
    fenwick.add(3, 5);
    cout << fenwick.rangeSum(1, 7) << '\n';
    return 0;
}
